/** pieces_cover_once's seed and draw size: the same stream every target draws. */
export const SEED_PIECES_COVER_ONCE = 1000003n;
export const PROPS_PIECES_COVER_ONCE = 2000;
export const PROP_LEN_PIECES_COVER_ONCE = 8;
export function check_pieces_cover_once_definedness(): LawStats {
  let total = 0; let tested = 0; let vacuous = 0; let failed = 0;
  for (const [shards_0, has_exc_1, has_timed_2, serial_active_3, t_4] of corpus_pieces_cover_once()) {
    const [ok, v] = law_pieces_cover_once(shards_0, has_exc_1, has_timed_2, serial_active_3, t_4);
    total++; if (!ok) { failed++; tested++; } else if (v === "vacuous") vacuous++; else tested++;
  }
  const r = new Rng(SEED_PIECES_COVER_ONCE);
  for (let i = 0; i < PROPS_PIECES_COVER_ONCE; i++) {
    const shards_0 = gen_Nat(r, PROP_LEN_PIECES_COVER_ONCE); const has_exc_1 = gen_Bool(r, PROP_LEN_PIECES_COVER_ONCE); const has_timed_2 = gen_Bool(r, PROP_LEN_PIECES_COVER_ONCE); const serial_active_3 = gen_Bool(r, PROP_LEN_PIECES_COVER_ONCE); const t_4 = gen_Test(r, PROP_LEN_PIECES_COVER_ONCE); const [ok, v] = law_pieces_cover_once(shards_0, has_exc_1, has_timed_2, serial_active_3, t_4);
    total++; if (!ok) { failed++; tested++; } else if (v === "vacuous") vacuous++; else tested++;
  }
  const isVacuous = total > 0 && tested === 0;
  return { total, tested, vacuous, failed, isVacuous, passed: failed === 0 && !isVacuous };
}

